package dev.odin.controls;
import android.content.*;import android.os.*;
/** Root's lock serializes frame ownership with OEM handoff. */
final class ZoneSession {
 static final String DARK="-16777216",FRAME="zoneFrame",SIGNATURE="zoneSignature",STOCK="zoneStockColor";static volatile boolean writing;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("profile",0);}
 static boolean present(Context c){return Build.MODEL.equals("Odin2")&&prefs(c).contains(FRAME);}
 static boolean owned(Context c){return present(c)&&DeviceState.ledSignature(c).equals(prefs(c).getString(SIGNATURE,""));}
 static String mask(Context c){StringBuilder m=new StringBuilder();for(String k:new String[]{"left_joystick_light_enabled","right_joystick_light_enabled","left_handle_light_enabled","right_handle_light_enabled"})m.append(DeviceState.get(c,k).equals("1")?'1':'0');return m.toString();}
 static ZoneFrame stock(Context c){String raw=DeviceState.get(c,"led_light_picker_color"),level=DeviceState.get(c,"led_light_brightness_percent");String color=raw.equals("null")?"000000":String.format(java.util.Locale.ROOT,"%06X",Long.parseLong(raw)&0xffffff);int percent=level.equals("null")?100:Math.round(Float.parseFloat(level)*100);return new ZoneFrame(new String[]{color,color,color,color},new int[]{percent,percent,percent,percent},mask(c));}
 static ZoneFrame frame(Context c){return ZoneFrame.parse(prefs(c).getString(FRAME,""),stock(c));}
 static boolean handles(Context c,String args){return Build.MODEL.equals("Odin2")&&(args.startsWith("light-zones ")||args.startsWith("light-groups ")||args.startsWith("light-one ")||args.equals("light-off")||args.equals("restore-light")||args.startsWith("light "));}
 static void forget(Context c){prefs(c).edit().remove(FRAME).remove(SIGNATURE).remove(STOCK).commit();c.stopService(new Intent(c,ZoneService.class));}
 static void release(Context c)throws Exception{synchronized(Root.class){if(!present(c)){c.stopService(new Intent(c,ZoneService.class));return;}if(owned(c))return;writing=true;try{String fallback=prefs(c).getString(STOCK,null);if(DARK.equals(DeviceState.get(c,"led_light_picker_color"))&&fallback!=null){Root.call(fallback.equals("null")?"settings --user 0 delete system led_light_picker_color":"settings --user 0 put system led_light_picker_color "+Long.parseLong(fallback));if(!DeviceState.get(c,"led_light_picker_color").equals(fallback))throw new java.io.IOException("Stock LED color could not be restored");}forget(c);DeviceState.ownLED(c,"System LEDs");}finally{writing=false;}}}
 static String run(Context c,String args)throws Exception{if(present(c)&&!owned(c))release(c);if(args.equals("restore-light")||args.startsWith("light ")){String result=Root.runDirect(c,args);forget(c);return result;}if(args.equals("light-off")&&!present(c))return Root.runDirect(c,args);
  ZoneFrame before=owned(c)?frame(c):stock(c),next=ZoneFrame.parse(args,before);String original=present(c)?prefs(c).getString(STOCK,"null"):DeviceState.get(c,"led_light_picker_color");String brightness=DeviceState.get(c,"led_light_brightness_percent");writing=true;try{if(!owned(c))Root.runDirect(c,"light-zones-prepare");String result=Root.runDirect(c,next.request().replace("light-zones ","light-zones-fast ")+" "+brightness);if(!DARK.equals(DeviceState.get(c,"led_light_picker_color"))||!brightness.equals(DeviceState.get(c,"led_light_brightness_percent"))||!next.mask.equals(mask(c)))throw new java.io.IOException("Stock lighting changed during the LED write");prefs(c).edit().putString(FRAME,next.request()).putString(STOCK,original).putString(SIGNATURE,DeviceState.ledSignature(c)).commit();ControlNotifications.clear(c,ControlNotifications.LED_ALERT);ensure(c,true);return result;}catch(Exception e){if(DARK.equals(DeviceState.get(c,"led_light_picker_color")))Root.call(original.equals("null")?"settings --user 0 delete system led_light_picker_color":"settings --user 0 put system led_light_picker_color "+Long.parseLong(original));forget(c);throw e;}finally{writing=false;}}
 static void ensure(Context c){ensure(c,false);}
 static void ensure(Context c,boolean applied){if(!present(c)||ZoneService.active)return;try{c.startForegroundService(new Intent(c,ZoneService.class).putExtra("applied",applied));}catch(android.app.ForegroundServiceStartNotAllowedException e){android.util.Log.i("RavenZones","LED restore deferred until an allowed app or tile entry");}}
 static void resume(Context c)throws Exception{synchronized(Root.class){if(!c.getSystemService(PowerManager.class).isInteractive())return;if(present(c)&&!owned(c)){release(c);return;}if(owned(c)&&!mask(c).equals("0000"))Root.run(c,frame(c).request());}}
 static void sleep(Context c)throws Exception{synchronized(Root.class){if(!c.getSystemService(PowerManager.class).isInteractive()&&owned(c))Root.runDirect(c,"light-zones-sleep");}}
}
